using System;
using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "TwistedScrollOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/TwistedScroll Omen Data")]
public class TwistedScrollOmenData : OmenData
{
	[Header("Twisted Scroll")]
	[SerializeField]
	private GameObjectReference runesPanelGameObjectReference;

	[SerializeField]
	private OnStartOfBattleOmenData startOfBattleOmenData;

	[SerializeField]
	private MapHandler mapHandler;

	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		RunesPanelInitializer runesPanelInitializer = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();
		omenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			RandomUtilities.SetUnityEngineRandomInitStateSeed(mapHandler.GetSeedWithCurrentMapPlayerTracker());
			runesPanelInitializer.ShuffleVirtues();
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.TwistedScrollOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.TwistedScrollOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return startOfBattleOmenData.GetStartOfBattleLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
